   1→"use client";
   2→
   3→import { startTransition, useEffect, useMemo, useRef, useState } from "react";
   4→import clsx from "clsx";
   5→import {
   6→  ArrowRight,
   7→  BookUser,
   8→  Building2,
   9→  CalendarSync,
  10→  ChartColumn,
  11→  Download,
  12→  LoaderCircle,
  13→  RefreshCw,
  14→  Users,
  15→} from "lucide-react";
  16→import Image from "next/image";
  17→import Link from "next/link";
  18→import { useRouter } from "next/navigation";
  19→import { getProcedureType, PROCEDURE_STEPS } from "@/lib/constants";
  20→import { ProcedureStepper } from "@/components/procedure-stepper";
  21→import { UserAdminPanel } from "@/components/user-admin-panel";
  22→import type {
  23→  AuthUser,
  24→  DashboardColumn,
  25→  DashboardDetail,
  26→  DashboardRow,
  27→  RecruitmentRequest,
  28→  UserRecord,
  29→} from "@/lib/types";
  30→
  31→type DashboardShellProps = {
  32→  columns: DashboardColumn[];
  33→  rows: DashboardRow[];
  34→  initialDetail: DashboardDetail | null;
  35→  currentUser: AuthUser;
  36→  users: UserRecord[];
  37→  departments: Array<{ deptCode: string; deptName: string }>;
  38→};
  39→
  40→const HIDDEN_IN_ALL_VIEW = new Set([
  41→  "(최초신청) 초빙분야",
  42→  "(최초신청) 학과요청사유",
  43→  "첨단학과신설 특별 TO 배정(안) 일반",
  44→  "첨단학과신설 특별 TO 배정(안) 전담",
  45→  "첨단학과신설 특별 TO 배정(안) 外",
  46→  "첨단학과신설 특별 TO 배정(안) 계",
  47→  "배정사유",
  48→  "본부 배정의견",
  49→  "BIGs(전임비율 제외)",
  50→]);
  51→
  52→function formatValue(value: string | number | null | undefined) {
  53→  if (value === null || value === undefined || value === "") return "-";
  54→  if (typeof value === "number") return Number.isInteger(value) ? String(value) : value.toFixed(2);
  55→  return value;
  56→}
  57→
  58→function formatCellValue(columnKey: string, value: string | number | null | undefined) {
  59→  return formatValue(value);
  60→}
  61→
  62→function getCurrentRequest(detail: DashboardDetail | null, selectedRequestId: number | null) {
  63→  if (!detail || !detail.recruitmentRequests.length) return null;
  64→  return (
  65→    detail.recruitmentRequests.find((request) => request.id === selectedRequestId) ??
  66→    detail.recruitmentRequests[0]
  67→  );
  68→}
  69→
  70→function getRequestProgressMeta(request: RecruitmentRequest) {
  71→  const procedureType = getProcedureType(request.hiringType);
  72→  const steps = PROCEDURE_STEPS[procedureType];
  73→  const currentIndex = Math.max(steps.findIndex((step) => step.stepKey === request.status), 0);
  74→  return {
  75→    stepTitle: steps[currentIndex]?.title ?? request.status,
  76→    percent: Math.round(((currentIndex + 1) / steps.length) * 100),
  77→  };
  78→}
  79→
  80→export function DashboardShell({
  81→  columns,
  82→  rows,
  83→  initialDetail,
  84→  currentUser,
  85→  users,
  86→  departments,
  87→}: DashboardShellProps) {
  88→  const router = useRouter();
  89→  const tableScrollRef = useRef<HTMLDivElement | null>(null);
  90→  const [selectedGroup, setSelectedGroup] = useState("전체 보기");
  91→  const [collegeFilter, setCollegeFilter] = useState("all");
  92→  const [departmentFilter, setDepartmentFilter] = useState("all");
  93→  const [hiringTypeFilter, setHiringTypeFilter] = useState("all");
  94→  const [selectedRowId, setSelectedRowId] = useState<number | null>(
  95→    initialDetail?.row.id ?? rows[0]?.id ?? null,
  96→  );
  97→  const [detail, setDetail] = useState<DashboardDetail | null>(initialDetail);
  98→  const [selectedRequestId, setSelectedRequestId] = useState<number | null>(
  99→    initialDetail?.row.requestId ?? initialDetail?.recruitmentRequests[0]?.id ?? null,
 100→  );
 101→  const [loadingDetail, setLoadingDetail] = useState(false);
 102→  const [saving, setSaving] = useState(false);
 103→  const [draftStatus, setDraftStatus] = useState("");
 104→  const [draftAction, setDraftAction] = useState("");
 105→  const [animateColumns, setAnimateColumns] = useState(false);
 106→
 107→  useEffect(() => {
 108→    const request = getCurrentRequest(detail, selectedRequestId);
 109→    setSelectedRequestId(request?.id ?? null);
 110→    setDraftStatus(request?.status ?? "");
 111→    setDraftAction(request?.nextAction ?? "");
 112→  }, [detail, selectedRequestId]);
 113→
 114→  useEffect(() => {
 115→    setAnimateColumns(true);
 116→    const timer = window.setTimeout(() => setAnimateColumns(false), 220);
 117→    return () => window.clearTimeout(timer);
 118→  }, [selectedGroup]);
 119→
 120→  useEffect(() => {
 121→    const reset = () => {
 122→      if (tableScrollRef.current) tableScrollRef.current.scrollLeft = 0;
 123→    };
 124→    reset();
 125→    const frame = window.requestAnimationFrame(reset);
 126→    return () => window.cancelAnimationFrame(frame);
 127→  }, [selectedGroup]);
 128→
 129→  const selectedRequest = useMemo(
 130→    () => getCurrentRequest(detail, selectedRequestId),
 131→    [detail, selectedRequestId],
 132→  );
 133→
 134→  const collegeOptions = useMemo(
 135→    () => [...new Set(rows.map((row) => String(row.college ?? "")).filter(Boolean))],
 136→    [rows],
 137→  );
 138→
 139→  const departmentOptions = useMemo(
 140→    () => [...new Set(rows.map((row) => String(row.deptName ?? "")).filter(Boolean))],
 141→    [rows],
 142→  );
 143→
 144→  const filteredRows = useMemo(
 145→    () =>
 146→      rows.filter((row) => {
 147→        const collegeMatch = collegeFilter === "all" || String(row.college ?? "") === collegeFilter;
 148→        const departmentMatch =
 149→          departmentFilter === "all" || String(row.deptName ?? "") === departmentFilter;
 150→        const hiringTypeMatch =
 151→          hiringTypeFilter === "all" || String(row.values["채용구분"] ?? "") === hiringTypeFilter;
 152→        return collegeMatch && departmentMatch && hiringTypeMatch;
 153→      }),
 154→    [rows, collegeFilter, departmentFilter, hiringTypeFilter],
 155→  );
 156→
 157→  const selectedProcedureSteps = useMemo(() => {
 158→    if (!selectedRequest) return [];
 159→    const procedureType = getProcedureType(selectedRequest.hiringType);
 160→    return PROCEDURE_STEPS[procedureType].map((step) => ({
 161→      procedureType,
 162→      stepKey: step.stepKey,
 163→      stepTitle: step.title,
 164→      stepDescription: step.description,
 165→      ownerAction: step.ownerAction,
 166→      stepOrder: step.order,
 167→    }));
 168→  }, [selectedRequest]);
 169→
 170→  const selectedStep = selectedProcedureSteps.find((step) => step.stepKey === selectedRequest?.status);
 171→
 172→  const columnGroups = useMemo(() => {
 173→    const groups = new Map<string, { startIndex: number; count: number }>();
 174→    columns.forEach((column, index) => {
 175→      const existing = groups.get(column.groupLabel);
 176→      if (existing) existing.count += 1;
 177→      else groups.set(column.groupLabel, { startIndex: index, count: 1 });
 178→    });
 179→
 180→    return [...groups.entries()].map(([label, meta], groupIndex) => ({
 181→      label,
 182→      startIndex: meta.startIndex,
 183→      count: meta.count,
 184→      groupIndex,
 185→    }));
 186→  }, [columns]);
 187→
 188→  const visibleColumns = useMemo(() => {
 189→    if (selectedGroup === "전체 보기") {
 190→      return columns.filter(
 191→        (column) =>
 192→          (
 193→            !HIDDEN_IN_ALL_VIEW.has(column.key) &&
 194→            !(column.groupLabel === "초빙 정보" && column.key !== "(최종) 초빙분야") &&
 195→            column.groupLabel !== "첨단학과신설 특별 TO 배정(안)" &&
 196→            column.groupLabel !== "배정 판단"
 197→          ) ||
 198→          column.groupLabel === "2026 실적" ||
 199→          column.groupLabel === "2025 실적" ||
 200→          column.groupLabel === "참고/비고",
 201→      );
 202→    }
 203→    return columns.filter(
 204→      (column) => column.groupLabel === "기본 정보" || column.groupLabel === selectedGroup,
 205→    );
 206→  }, [columns, selectedGroup]);
 207→
 208→  const visibleGroups = useMemo(() => {
 209→    const groups = new Map<string, { label: string; count: number; width: number; groupIndex: number }>();
 210→    visibleColumns.forEach((column, index) => {
 211→      const existing = groups.get(column.groupLabel);
 212→      const width = index < 2 ? 220 : 190;
 213→      const groupIndex = columnGroups.find((group) => group.label === column.groupLabel)?.groupIndex ?? 0;
 214→
 215→      if (existing) {
 216→        existing.count += 1;
 217→        existing.width += width;
 218→        return;
 219→      }
 220→
 221→      groups.set(column.groupLabel, {
 222→        label: column.groupLabel,
 223→        count: 1,
 224→        width,
 225→        groupIndex,
 226→      });
 227→    });
 228→
 229→    return [...groups.values()];
 230→  }, [columnGroups, visibleColumns]);
 231→
 232→  const groupIndexByColumn = useMemo(() => {
 233→    const lookup = new Map<string, number>();
 234→    columnGroups.forEach((group) => {
 235→      columns
 236→        .filter((column) => column.groupLabel === group.label)
 237→        .forEach((column) => lookup.set(column.key, group.groupIndex));
 238→    });
 239→    return lookup;
 240→  }, [columnGroups, columns]);
 241→
 242→  const summary = useMemo(() => {
 243→    const deptMap = new Map<string, DashboardRow>();
 244→    filteredRows.forEach((row) => {
 245→      if (row.deptCode && !deptMap.has(row.deptCode)) {
 246→        deptMap.set(row.deptCode, row);
 247→      }
 248→    });
 249→
 250→    const deptRows = [...deptMap.values()];
 251→    const parseNumber = (value: string | number | null | undefined) => {
 252→      if (typeof value === "number") {
 253→        return Number.isFinite(value) ? value : 0;
 254→      }
 255→
 256→      const matched = String(value ?? "").match(/-?\d+(?:\.\d+)?/);
 257→      if (!matched) return 0;
 258→      const num = Number(matched[0]);
 259→      return Number.isFinite(num) ? num : 0;
 260→    };
 261→
 262→    const total2025Request = deptRows.reduce((sum, row) => sum + parseNumber(row.values["25 TO신청(명)"]), 0);
 263→    const total2025Allocated = deptRows.reduce((sum, row) => sum + parseNumber(row.values["25 TO배정(명)"]), 0);
 264→    const total2025Result = deptRows.reduce((sum, row) => sum + parseNumber(row.values["25 TO채용(명)"]), 0);
 265→    const total2026Request = deptRows.reduce((sum, row) => sum + parseNumber(row.values["26 TO신청(명)"]), 0);
 266→    const total2026Allocated = deptRows.reduce((sum, row) => sum + parseNumber(row.values["26 TO배정(명)"]), 0);
 267→    const total2026Result = deptRows.reduce((sum, row) => sum + parseNumber(row.values["26 채용결과(명) 합계"]), 0);
 268→    const total2027Request = filteredRows.reduce((sum, row) => sum + parseNumber(row.values["??  泥?怨?" ]), 0);
 269→    const total2027Allocated = deptRows.reduce(
 270→      (sum, row) =>
 271→        sum +
 272→        parseNumber(row.values["일반TO 배정(안) 계"]) +
 273→        parseNumber(row.values["첨단학과신설 특별 TO 배정(안) 계"]) +
 274→        parseNumber(row.values["총장TO 배정(안) 계"]),
 275→      0,
 276→    );
 277→    const total2027Result = filteredRows.reduce(
 278→      (sum, row) => sum + (row.requestId && row.values["완료"] === "done" ? 1 : 0),
 279→      0,
 280→    );
 281→
 282→    return {
 283→      total2025Request,
 284→      total2025Allocated,
 285→      total2025Result,
 286→      total2026Request,
 287→      total2026Allocated,
 288→      total2026Result,
 289→      total2027Request,
 290→      total2027Allocated,
 291→      total2027Result,
 292→    };
 293→  }, [filteredRows]);
 294→  const topStats = useMemo(() => {
 295→    const initialFieldCount = filteredRows.filter((row) => row.requestId !== null && row.values["(최초신청) 초빙분야"]).length;
 296→    const finalFieldCount = filteredRows.filter((row) => row.requestId !== null && row.values["(최종) 초빙분야"]).length;
 297→    const regularCount = filteredRows.filter((row) => String(row.values["채용구분"] ?? "").includes("정시")).length;
 298→    const rollingCount = filteredRows.filter((row) => String(row.values["채용구분"] ?? "").includes("상시")).length;
 299→    const progressValues = filteredRows
 300→      .map((row) => String(row.values["진행률"] ?? "").replace("%", ""))
 301→      .map((value) => Number(value))
 302→      .filter((value) => Number.isFinite(value) && value > 0);
 303→    const averageProgress = progressValues.length
 304→      ? Math.round(progressValues.reduce((sum, value) => sum + value, 0) / progressValues.length)
 305→      : 0;
 306→
 307→    return {
 308→      initialFieldCount,
 309→      finalFieldCount,
 310→      regularCount,
 311→      rollingCount,
 312→      averageProgress,
 313→    };
 314→  }, [filteredRows]);
 315→
 316→  function getGroupTone(_groupIndex: number) {
 317→    return "bg-[#fafbfc]";
 318→  }
 319→
 320→  async function handleRowSelect(row: DashboardRow) {
 321→    setSelectedRowId(row.id);
 322→    setLoadingDetail(true);
 323→    try {
 324→      const response = await fetch(`/api/dashboard/${row.id}`);
 325→      if (!response.ok) throw new Error("Failed to load detail");
 326→      const nextDetail = (await response.json()) as DashboardDetail;
 327→      setDetail(nextDetail);
 328→      setSelectedRequestId(row.requestId ?? nextDetail.recruitmentRequests[0]?.id ?? null);
 329→    } finally {
 330→      setLoadingDetail(false);
 331→    }
 332→  }
 333→
 334→  async function handleSaveStatus(request: RecruitmentRequest) {
 335→    setSaving(true);
 336→    try {
 337→      const response = await fetch(`/api/recruitment-requests/${request.id}`, {
 338→        method: "PATCH",
 339→        headers: { "Content-Type": "application/json" },
 340→        body: JSON.stringify({ status: draftStatus, nextAction: draftAction }),
 341→      });
 342→      if (!response.ok) throw new Error("Failed to update request");
 343→      const updated = (await response.json()) as RecruitmentRequest;
 344→      startTransition(() => {
 345→        setDetail((current) =>
 346→          current
 347→            ? {
 348→                ...current,
 349→                recruitmentRequests: current.recruitmentRequests.map((item) =>
 350→                  item.id === updated.id ? updated : item,
 351→                ),
 352→              }
 353→            : current,
 354→        );
 355→      });
 356→    } finally {
 357→      setSaving(false);
 358→    }
 359→  }
 360→
 361→  async function handleLogout() {
 362→    await fetch("/api/auth/logout", { method: "POST" });
 363→    router.push("/login");
 364→    router.refresh();
 365→  }
 366→
 367→  return (
 368→    <div className="min-h-screen bg-[var(--page-bg)] text-[var(--text-body)]">
 369→      <div className="mx-auto flex max-w-[1880px] flex-col gap-8 px-4 py-8 md:px-8 xl:px-10">
 370→        <section className="relative overflow-hidden rounded-[10px] bg-[var(--card-bg)] p-8 shadow-[0_1px_3px_rgba(0,0,0,0.06)]">
 371→          <div className="absolute inset-x-0 top-0 h-px bg-[var(--divider)]" />
 372→          <div className="flex flex-col gap-8 xl:grid xl:grid-cols-[1.2fr_0.8fr] xl:items-end">
 373→            <div className="space-y-6">
 374→              <div className="flex flex-col gap-5 md:flex-row md:items-start">
 375→                <div className="flex h-24 w-24 shrink-0 items-center justify-center rounded-[10px] bg-[var(--page-bg)] p-3">
 376→                  <Image
 377→                    src="/logo_SKKU_colored.png"
 378→                    alt="성균관대학교 로고"
 379→                    width={84}
 380→                    height={84}
 381→                    unoptimized
 382→                    className="h-full w-full object-contain"
 383→                  />
 384→                </div>
 385→
 386→                <div className="max-w-4xl space-y-4">
 387→                  <p className="font-mono text-xs uppercase tracking-[0.28em] text-[var(--text-secondary)]">
 388→                    Sungkyunkwan University Faculty Recruiting Platform
 389→                  </p>
 390→                  <h1 className="text-3xl font-semibold tracking-tight text-[var(--text-title)] md:text-5xl">
 391→                    SKKU 교원채용 All-In-One
 392→                  </h1>
 393→                  <div className="space-y-2">
 394→                    <p className="text-sm font-medium tracking-[0.08em] text-[#c2a96a] md:text-base">
 395→                      인류와 미래사회를 위한 담대한 도전 Inspiring Future, Grand Challenge
 396→                    </p>
 397→                    <p className="max-w-3xl text-sm leading-7 text-[var(--text-body)] md:text-base">
 398→                      성균관대학교 교원 채용의 모든 것을 이 사이트에 담으려 노력했습니다.
 399→                      정시와 상시 전형, TO 배정, 학과 요청, 후보자 검토, 단계별 입력과 보고 흐름을
 400→                      한곳에서 연결해 학과와 본부가 같은 기준으로 현황을 확인할 수 있도록 구성했습니다.
 401→                    </p>
 402→                  </div>
 403→                  <div className="flex flex-wrap gap-2 text-xs text-[var(--text-secondary)]">
 404→                    <span className="rounded-full bg-[var(--page-bg)] px-3 py-1 font-mono">
 405→                      {currentUser.username}
 406→                    </span>
 407→                    <span className="rounded-full bg-[var(--page-bg)] px-3 py-1 font-mono">
 408→                      {currentUser.role}
 409→                    </span>
 410→                    {currentUser.departmentCode ? (
 411→                      <span className="rounded-full bg-[var(--page-bg)] px-3 py-1 font-mono">
 412→                        {currentUser.departmentCode}
 413→                      </span>
 414→                    ) : null}
 415→                  </div>
 416→                </div>
 417→              </div>
 418→            </div>
 419→            <div className="space-y-4">
 420→              <div className="rounded-[10px] bg-[var(--page-bg)] p-5">
 421→                <p className="font-mono text-[11px] uppercase tracking-[0.24em] text-[var(--text-secondary)]">
 422→                  Strategic Overview
 423→                </p>
 424→                <div className="mt-4 grid gap-3 text-sm leading-6 text-[var(--text-body)]">
 425→                  <div className="rounded-[8px] border border-[var(--divider)] bg-[var(--card-bg)] px-4 py-3">
 426→                    2025·2026 실적과 2027 초빙·배정 현황을 한 번에 비교해 학과별 흐름을 빠르게 파악할 수 있습니다.
 427→                  </div>
 428→                  <div className="rounded-[8px] border border-[var(--divider)] bg-[var(--card-bg)] px-4 py-3">
 429→                    권한별 입력과 승인 흐름을 분리해 학과장, 인사팀, 최고관리자가 각자 필요한 작업만 바로 처리할 수 있습니다.
 430→                  </div>
 431→                </div>
 432→              </div>
 433→              <div className="flex flex-wrap gap-2 xl:justify-end">
 434→                {(currentUser.role === "VIP" || currentUser.role === "ADMIN") ? (
 435→                  <Link
 436→                    href="/admin"
 437→                    className="inline-flex items-center gap-2 rounded-full bg-[var(--deep-green)] px-4 py-2 text-sm font-medium text-white transition-colors hover:opacity-90"
 438→                  >
 439→                    관리자 페이지
 440→                  </Link>
 441→                ) : null}
 442→                <Link
 443→                  href="/candidates"
 444→                  className="inline-flex items-center gap-2 rounded-full border border-[var(--divider)] bg-[var(--card-bg)] px-4 py-2 text-sm font-medium text-[var(--text-body)] transition-colors hover:bg-[var(--page-bg)]"
 445→                >
 446→                  후보자 입력
 447→                </Link>
 448→                <button
 449→                  type="button"
 450→                  onClick={() => selectedRowId && handleRowSelect(filteredRows.find((row) => row.id === selectedRowId) ?? filteredRows[0] ?? rows[0])}
 451→                  className="inline-flex cursor-pointer items-center gap-2 self-start rounded-full border border-[var(--divider)] bg-[var(--card-bg)] px-4 py-2 text-sm font-medium text-[var(--text-body)] transition-colors hover:bg-[var(--page-bg)]"
 452→                >
 453→                  <RefreshCw className="h-4 w-4" />
 454→                  현재 화면 다시 불러오기
 455→                </button>
 456→                <button
 457→                  type="button"
 458→                  onClick={handleLogout}
 459→                  className="inline-flex cursor-pointer items-center gap-2 self-start rounded-full border border-[var(--divider)] bg-[var(--card-bg)] px-4 py-2 text-sm font-medium text-[#c44] transition-colors hover:bg-red-50"
 460→                >
 461→                  로그아웃
 462→                </button>
 463→              </div>
 464→            </div>
 465→          </div>
 466→          <div className="mt-8 grid gap-4 md:grid-cols-2 xl:grid-cols-4">
 467→            {[
 468→              {
 469→                label: "(최초신청) 초빙분야",
 470→                value: topStats.initialFieldCount,
 471→                suffix: "건",
 472→                icon: BookUser,
 473→              },
 474→              {
 475→                label: "(최종) 초빙분야",
 476→                value: topStats.finalFieldCount,
 477→                suffix: "건",
 478→                icon: Building2,
 479→              },
 480→              {
 481→                label: "정시/상시",
 482→                value: `정시 ${topStats.regularCount} · 상시 ${topStats.rollingCount}`,
 483→                suffix: "",
 484→                icon: CalendarSync,
 485→              },
 486→              {
 487→                label: "진행률(평균)",
 488→                value: `${topStats.averageProgress}%`,
 489→                suffix: "",
 490→                icon: Users,
 491→              },
 492→            ].map((metric) => {
 493→              const Icon = metric.icon;
 494→              return (
 495→                <div
 496→                  key={metric.label}
 497→                  className="rounded-[10px] bg-[var(--page-bg)] p-5"
 498→                >
