 54→
 55→export function AdminRequestSheet({ initialRows }: AdminRequestSheetProps) {
 56→  const [rows, setRows] = useState(initialRows);
 57→  const [message, setMessage] = useState("");
 58→  const [uploading, setUploading] = useState(false);
 59→  const [savingAll, setSavingAll] = useState(false);
 60→  const [dirtyIds, setDirtyIds] = useState<number[]>([]);
 61→  const cellRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement | null>>({});
 62→
 63→  function markDirty(requestId: number) {
 64→    setDirtyIds((current) => (current.includes(requestId) ? current : [...current, requestId]));
 65→  }
 66→
 67→  function updateCell(rowIndex: number, columnKey: (typeof EDITABLE_COLUMNS)[number]["key"], value: string) {
 68→    setRows((current) =>
 69→      current.map((item, index) => (index === rowIndex ? { ...item, [columnKey]: value } : item)),
 70→    );
 71→    markDirty(rows[rowIndex].requestId);
 72→  }
 73→
 74→  function focusCell(rowIndex: number, columnIndex: number) {
 75→    const key = `${rowIndex}:${columnIndex}`;
 76→    cellRefs.current[key]?.focus();
 77→  }
 78→
 79→  function handlePaste(
 80→    event: React.ClipboardEvent<HTMLInputElement | HTMLTextAreaElement>,
 81→    rowIndex: number,
 82→    columnIndex: number,
 83→  ) {
 84→    const text = event.clipboardData.getData("text");
 85→    if (!text.includes("\t") && !text.includes("\n")) return;
 86→
 87→    event.preventDefault();
 88→    const matrix = text
 89→      .replace(/\r/g, "")
 90→      .split("\n")
 91→      .filter((line) => line.length > 0)
 92→      .map((line) => line.split("\t"));
 93→
 94→    setRows((current) =>
 95→      current.map((row, currentRowIndex) => {
 96→        const pastedRow = matrix[currentRowIndex - rowIndex];
 97→        if (!pastedRow) return row;
 98→
 99→        const nextRow = { ...row };
100→        pastedRow.forEach((cellValue, offset) => {
101→          const column = EDITABLE_COLUMNS[columnIndex + offset];
102→          if (!column) return;
103→          nextRow[column.key] = cellValue;
104→        });
105→        return nextRow;
106→      }),
107→    );
108→
109→    const touchedIds = matrix
110→      .map((_, offset) => rows[rowIndex + offset]?.requestId)
111→      .filter((value): value is number => Boolean(value));
112→    setDirtyIds((current) => [...new Set([...current, ...touchedIds])]);
113→  }
114→
115→  function handleKeyDown(
116→    event: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>,
117→    rowIndex: number,
118→    columnIndex: number,
119→  ) {
120→    if (event.key === "ArrowRight") {
121→      event.preventDefault();
122→      focusCell(rowIndex, Math.min(columnIndex + 1, EDITABLE_COLUMNS.length - 1));
123→    } else if (event.key === "ArrowLeft") {
124→      event.preventDefault();
125→      focusCell(rowIndex, Math.max(columnIndex - 1, 0));
126→    } else if (event.key === "ArrowDown") {
127→      event.preventDefault();
128→      focusCell(Math.min(rowIndex + 1, rows.length - 1), columnIndex);
129→    } else if (event.key === "ArrowUp") {
130→      event.preventDefault();
131→      focusCell(Math.max(rowIndex - 1, 0), columnIndex);
132→    } else if (event.key === "Tab" && !event.shiftKey) {
133→      event.preventDefault();
134→      const nextColumnIndex = columnIndex + 1;
135→      if (nextColumnIndex < EDITABLE_COLUMNS.length) {
136→        focusCell(rowIndex, nextColumnIndex);
137→      } else if (rowIndex < rows.length - 1) {
138→        focusCell(rowIndex + 1, 0);
139→      }
140→    } else if (event.key === "Tab" && event.shiftKey) {
141→      event.preventDefault();
142→      const prevColumnIndex = columnIndex - 1;
143→      if (prevColumnIndex >= 0) {
144→        focusCell(rowIndex, prevColumnIndex);
145→      } else if (rowIndex > 0) {
146→        focusCell(rowIndex - 1, EDITABLE_COLUMNS.length - 1);
147→      }
148→    }
149→  }
150→
151→  async function handleSaveRow(rowIndex: number) {
152→    const row = rows[rowIndex];
153→    const response = await fetch("/api/admin/request-sheet", {
154→      method: "PATCH",
155→      headers: { "Content-Type": "application/json" },
156→      body: JSON.stringify({ requestId: row.requestId, values: buildPayload(row) }),
157→    });
158→    const data = (await response.json().catch(() => ({}))) as { message?: string };
159→    setMessage(response.ok ? "DB 연동 편집 시트를 저장했습니다." : data.message ?? "저장에 실패했습니다.");
160→    if (response.ok) {
161→      setDirtyIds((current) => current.filter((id) => id !== row.requestId));
162→    }
163→  }
164→
165→  async function handleSaveAll() {
166→    if (!dirtyIds.length) {
167→      setMessage("저장할 변경 사항이 없습니다.");
168→      return;
169→    }
170→
171→    setSavingAll(true);
172→    for (const requestId of dirtyIds) {
173→      const rowIndex = rows.findIndex((row) => row.requestId === requestId);
174→      if (rowIndex !== -1) {
175→        await handleSaveRow(rowIndex);
176→      }
177→    }
178→    setSavingAll(false);
179→    setMessage("변경한 항목을 모두 저장했습니다.");
180→  }
181→
182→  async function handleImport(event: React.ChangeEvent<HTMLInputElement>) {
183→    const file = event.target.files?.[0];
184→    if (!file) return;
185→
186→    setUploading(true);
187→    const formData = new FormData();
188→    formData.set("file", file);
189→
190→    const response = await fetch("/api/admin/request-sheet/import", {
191→      method: "POST",
192→      body: formData,
193→    });
194→    const data = (await response.json().catch(() => ({}))) as { message?: string; count?: number };
195→    if (response.ok) {
196→      setMessage(`엑셀 업로드를 반영했습니다. ${data.count ?? 0}개 항목을 갱신했습니다.`);
197→      window.location.reload();
198→      return;
199→    }
200→
201→    setMessage(data.message ?? "엑셀 업로드에 실패했습니다.");
202→    setUploading(false);
203→  }
204→
205→  return (
206→    <div>
207→      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
208→        <div className="flex flex-wrap gap-2">
209→          <button
210→            type="button"
211→            onClick={() => window.location.assign("/api/admin/request-sheet/export")}
212→            className="inline-flex items-center gap-2 rounded-[10px] border border-[#e5e7eb] bg-white px-4 py-2 text-sm text-[#374151]"
213→          >
214→            <Download className="h-4 w-4" />
215→            엑셀 다운로드
216→          </button>
