  1→"use client";
  2→
  3→import Link from "next/link";
  4→import { Save } from "lucide-react";
  5→import { useRef, useState } from "react";
  6→import type { AdminWorkflowColumn, AdminWorkflowMatrixRow } from "@/lib/types";
  7→
  8→type AdminWorkflowTableProps = {
  9→  columns: AdminWorkflowColumn[];
 10→  initialRows: AdminWorkflowMatrixRow[];
 11→};
 12→
 13→export function AdminWorkflowTable({ columns, initialRows }: AdminWorkflowTableProps) {
 14→  const [rows, setRows] = useState(initialRows);
 15→  const [message, setMessage] = useState("");
 16→  const [savingAll, setSavingAll] = useState(false);
 17→  const [dirtyIds, setDirtyIds] = useState<number[]>([]);
 18→  const cellRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement | null>>({});
 19→
 20→  function markDirty(requestId: number) {
 21→    setDirtyIds((current) => (current.includes(requestId) ? current : [...current, requestId]));
 22→  }
 23→
 24→  function updateCell(rowIndex: number, columnKey: string, value: string) {
 25→    setRows((current) =>
 26→      current.map((item, index) =>
 27→        index === rowIndex
 28→          ? {
 29→              ...item,
 30→              values: { ...item.values, [columnKey]: value },
 31→            }
 32→          : item,
 33→      ),
 34→    );
 35→    markDirty(rows[rowIndex].requestId);
 36→  }
 37→
 38→  function focusCell(rowIndex: number, columnIndex: number) {
 39→    cellRefs.current[`${rowIndex}:${columnIndex}`]?.focus();
 40→  }
 41→
 42→  function handlePaste(
 43→    event: React.ClipboardEvent<HTMLInputElement | HTMLTextAreaElement>,
 44→    rowIndex: number,
 45→    columnIndex: number,
 46→  ) {
 47→    const text = event.clipboardData.getData("text");
 48→    if (!text.includes("\t") && !text.includes("\n")) return;
 49→
 50→    event.preventDefault();
 51→    const matrix = text
 52→      .replace(/\r/g, "")
 53→      .split("\n")
 54→      .filter((line) => line.length > 0)
 55→      .map((line) => line.split("\t"));
 56→
 57→    setRows((current) =>
 58→      current.map((row, currentRowIndex) => {
 59→        const pastedRow = matrix[currentRowIndex - rowIndex];
 60→        if (!pastedRow) return row;
 61→
 62→        const values = { ...row.values };
 63→        pastedRow.forEach((cellValue, offset) => {
 64→          const column = columns[columnIndex + offset];
 65→          if (!column) return;
 66→          values[column.key] = cellValue;
 67→        });
 68→
 69→        return { ...row, values };
 70→      }),
 71→    );
 72→
 73→    const touchedIds = matrix
 74→      .map((_, offset) => rows[rowIndex + offset]?.requestId)
 75→      .filter((value): value is number => Boolean(value));
 76→    setDirtyIds((current) => [...new Set([...current, ...touchedIds])]);
 77→  }
 78→
 79→  function handleKeyDown(
 80→    event: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>,
 81→    rowIndex: number,
 82→    columnIndex: number,
 83→  ) {
 84→    if (event.key === "ArrowRight") {
 85→      event.preventDefault();
 86→      focusCell(rowIndex, Math.min(columnIndex + 1, columns.length - 1));
 87→    } else if (event.key === "ArrowLeft") {
 88→      event.preventDefault();
 89→      focusCell(rowIndex, Math.max(columnIndex - 1, 0));
 90→    } else if (event.key === "ArrowDown") {
 91→      event.preventDefault();
 92→      focusCell(Math.min(rowIndex + 1, rows.length - 1), columnIndex);
 93→    } else if (event.key === "ArrowUp") {
 94→      event.preventDefault();
 95→      focusCell(Math.max(rowIndex - 1, 0), columnIndex);
 96→    } else if (event.key === "Tab" && !event.shiftKey) {
 97→      event.preventDefault();
 98→      const nextColumnIndex = columnIndex + 1;
 99→      if (nextColumnIndex < columns.length) {
100→        focusCell(rowIndex, nextColumnIndex);
101→      } else if (rowIndex < rows.length - 1) {
102→        focusCell(rowIndex + 1, 0);
103→      }
104→    } else if (event.key === "Tab" && event.shiftKey) {
105→      event.preventDefault();
106→      const prevColumnIndex = columnIndex - 1;
107→      if (prevColumnIndex >= 0) {
108→        focusCell(rowIndex, prevColumnIndex);
109→      } else if (rowIndex > 0) {
110→        focusCell(rowIndex - 1, columns.length - 1);
111→      }
112→    }
113→  }
114→
115→  async function handleSaveRow(rowIndex: number) {
116→    const row = rows[rowIndex];
117→    const response = await fetch("/api/admin/workflow", {
118→      method: "PATCH",
119→      headers: { "Content-Type": "application/json" },
120→      body: JSON.stringify({
121→        requestId: row.requestId,
122→        values: row.values,
123→      }),
124→    });
125→    const data = (await response.json().catch(() => ({}))) as { message?: string };
126→    setMessage(response.ok ? "전형단계별 학과 입력시트를 저장했습니다." : data.message ?? "저장에 실패했습니다.");
127→    if (response.ok) {
128→      setDirtyIds((current) => current.filter((id) => id !== row.requestId));
129→    }
130→  }
131→
132→  async function handleSaveAll() {
133→    if (!dirtyIds.length) {
134→      setMessage("저장할 변경 사항이 없습니다.");
135→      return;
136→    }
137→
138→    setSavingAll(true);
139→    for (const requestId of dirtyIds) {
140→      const rowIndex = rows.findIndex((row) => row.requestId === requestId);
141→      if (rowIndex !== -1) {
142→        await handleSaveRow(rowIndex);
143→      }
144→    }
145→    setSavingAll(false);
146→    setMessage("변경한 항목을 모두 저장했습니다.");
147→  }
148→
149→  return (
150→    <div>
151→      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
152→        <button
153→          type="button"
154→          onClick={handleSaveAll}
155→          disabled={savingAll}
156→          className="inline-flex items-center gap-2 rounded-[10px] border border-[#6a7f48] bg-[#394727] px-4 py-2 text-sm text-[#f3f1d4] disabled:opacity-60"
157→        >
158→          <Save className="h-4 w-4" />
159→          {savingAll ? "일괄 저장 중..." : `변경행 일괄 저장 (${dirtyIds.length})`}
160→        </button>
161→        <p className="text-sm text-[#6b7280]">
162→          엑셀이나 구글시트에서 복사해 붙여넣으면 여러 단계 입력칸을 한 번에 채울 수 있습니다.
163→        </p>
164→      </div>
165→
166→      {message ? <p className="mb-4 rounded-[10px] bg-[#f0f9f4] px-4 py-3 text-sm text-[#374151]">{message}</p> : null}
167→
168→      <div className="max-h-[72vh] overflow-auto">
169→        <table className="min-w-[2400px] border-separate border-spacing-0 text-sm">
170→          <thead>
171→            <tr>
172→              {["소속대학", "학과명", "(최종) 초빙분야", "채용구분", "현재단계"].map((label, index) => (
173→                <th
174→                  key={label}
175→                  className="sticky top-0 z-30 border-b border-r border-[#e5e7eb] bg-[#f9fafb] px-4 py-4 text-center align-middle font-semibold text-[#111827]"
176→                  style={{ minWidth: index < 3 ? 220 : 160 }}
177→                >
178→                  {label}
179→                </th>
180→              ))}
181→              {columns.map((column) => (
182→                <th
183→                  key={column.key}
184→                  className="sticky top-0 z-20 border-b border-r border-[#e5e7eb] bg-[#f3f4f6] px-4 py-4 text-center align-middle font-semibold text-[#111827]"
185→                  style={{ minWidth: 220 }}
186→                >
187→                  <span className="block text-xs text-[#6b7280]">{column.stepKey}</span>
188→                  <span className="mt-1 block whitespace-pre-wrap">{column.label}</span>
189→                </th>
190→              ))}
191→              <th className="sticky top-0 z-20 border-b border-r border-[#e5e7eb] bg-[#f9fafb] px-4 py-4 text-center align-middle font-semibold text-[#111827]">
192→                작업
193→              </th>
194→            </tr>
195→          </thead>
196→          <tbody>
197→            {rows.map((row, rowIndex) => (
198→              <tr key={row.requestId} className={rowIndex % 2 === 0 ? "bg-white" : "bg-[#f9fafb]"}>
199→                <td className="border-b border-r border-[#f0f0f0] px-4 py-3">{row.college}</td>
200→                <td className="border-b border-r border-[#f0f0f0] px-4 py-3">{row.deptName}</td>
201→                <td className="border-b border-r border-[#f0f0f0] px-4 py-3 font-semibold text-[#111827]">{row.fieldName}</td>
202→                <td className="border-b border-r border-[#f0f0f0] px-4 py-3 text-center">{row.hiringType}</td>
203→                <td className="border-b border-r border-[#f0f0f0] px-4 py-3 text-center">{row.currentStatus}</td>
204→                {columns.map((column, columnIndex) => (
205→                  <td key={`${row.requestId}-${column.key}`} className="border-b border-r border-[#f0f0f0] px-3 py-3 align-top">
206→                    {column.inputType === "textarea" ? (
207→                      <textarea
208→                        ref={(node) => {
209→                          cellRefs.current[`${rowIndex}:${columnIndex}`] = node;
210→                        }}
211→                        rows={4}
212→                        value={row.values[column.key] ?? ""}
213→                        onChange={(event) => updateCell(rowIndex, column.key, event.target.value)}
214→                        onPaste={(event) => handlePaste(event, rowIndex, columnIndex)}
215→                        onKeyDown={(event) => handleKeyDown(event, rowIndex, columnIndex)}
216→                        className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs leading-6 text-[#111827] outline-none focus:border-[#7fb18f]"
217→                      />
218→                    ) : (
219→                      <input
220→                        ref={(node) => {
221→                          cellRefs.current[`${rowIndex}:${columnIndex}`] = node;
222→                        }}
223→                        type={column.inputType === "date" ? "text" : column.inputType}
224→                        value={row.values[column.key] ?? ""}
225→                        onChange={(event) => updateCell(rowIndex, column.key, event.target.value)}
226→                        onPaste={(event) => handlePaste(event, rowIndex, columnIndex)}
227→                        onKeyDown={(event) => handleKeyDown(event, rowIndex, columnIndex)}
228→                        placeholder={column.inputType === "date" ? "YYYY-MM-DD" : ""}
229→                        className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs text-[#111827] outline-none focus:border-[#7fb18f]"
230→                      />
231→                    )}
232→                  </td>
233→                ))}
234→                <td className="border-b border-r border-[#f0f0f0] px-4 py-3 text-center">
235→                  <div className="flex min-w-[180px] flex-col items-center gap-2">
236→                    <button
237→                      type="button"
238→                      onClick={() => handleSaveRow(rowIndex)}
239→                      className="rounded-[10px] bg-[#1f5b43] px-4 py-2 text-xs font-semibold text-white"
240→                    >
241→                      저장
242→                    </button>
243→                    <Link
244→                      href={`/procedures/${row.requestId}`}
245→                      className="rounded-[10px] border border-[#e5e7eb] bg-white px-4 py-2 text-xs font-semibold text-[#374151]"
246→                    >
247→                      절차 상세
248→                    </Link>
249→                  </div>
250→                </td>
251→              </tr>
252→            ))}
253→          </tbody>
254→        </table>
255→      </div>
256→    </div>
257→  );
258→}
